SELECT        ITP_INFORMECHECKLISTPT.IDInformeCheckList, ITP_RESPUESTACHECKLISTPT.IDPregunta, ITP_CHECKLISTPT.Pregunta, ITP_CHECKLISTPT.IDTipoPregunta, ITP_CHECKLISTPT.IDGrupo, ITP_CHECKLISTPT.IDCategoria, 
                         ITP_CATEGORIASCHECKLISTPT.Categoria, ITP_CHECKLISTPT.NumPregunta, ITP_RESPUESTACHECKLISTPT.RespuestaSi, ITP_RESPUESTACHECKLISTPT.RespuestaNo, ITP_RESPUESTACHECKLISTPT.RespuestaNA, 
                         ITP_RESPUESTACHECKLISTPT.Comentarios, ITP_RESPUESTACHECKLISTPT.EsNaranjaNoAceptable, ITP_INFORMECHECKLISTPT.IDContratista, ITP_INFORMECHECKLISTPT.NumPermisoTrabajo, 
                         ITP_INFORMECHECKLISTPT.OtroContratista, ITP_INFORMECHECKLISTPT.NumCertificadoAislamiento, ITP_INFORMECHECKLISTPT.ComentarioGeneral, format(ITP_INFORMECHECKLISTPT.fechaCreacion, 
                         'dd/MM/yyyy HH:mm:ss') AS fechaCreacion, ITP_INFORMECHECKLISTPT.IdUsuarioCreador, ITP_INFORMECHECKLISTPT.Zona, ITP_INFORMECHECKLISTPT.IdTipoTrabajo, ITP_INFORMECHECKLISTPT.IDSeguridad, 
                         ITP_INFORMECHECKLISTPT.IDTipoPermisoTrabajo
FROM            ITP_RESPUESTACHECKLISTPT JOIN
                         ITP_CHECKLISTPT ON ITP_RESPUESTACHECKLISTPT.IDPregunta = ITP_CHECKLISTPT.IDPregunta  JOIN
                         ITP_INFORMECHECKLISTPT ON ITP_RESPUESTACHECKLISTPT.IDInformeCheckList = ITP_INFORMECHECKLISTPT.IDInformeCheckList INNER JOIN
                         ITP_CATEGORIASCHECKLISTPT ON ITP_CHECKLISTPT.IDCategoria = ITP_CATEGORIASCHECKLISTPT.IDCategoria
ORDER BY ITP_RESPUESTACHECKLISTPT.IDInformeCheckList, ITP_RESPUESTACHECKLISTPT.IDPregunta